/* Types */
export type Account = {
	id: number,
	name: string,
	type: AccountType,
	currency: string,
	institution: string | null,
	openingBalanceCents: number,
	openingDate: string,
	archived: boolean,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type AccountError = { code: "notFound"; params: number } | { code: "emptyName" } | { code: "valuationNotFound"; params: number } | { code: "notValued" } | { code: "negativeValuation" } | { code: "duplicateValuationDate"; params: string } | { code: "valuationBeforeOpening"; params: string };

/**  An account with its balance at a given date. */
export type AccountSummary = {
	account: Account,
	/**
	 *  Balance from the operations; for investments and assets, the last valuation on or
	 *  before the date; for liabilities, minus the last outstanding capital. `None` for a
	 *  valued account without valuation yet.
	 */
	balanceCents: number | null,
	/**  Date of the valuation behind the balance of a valued account. */
	valuedOn: string | null,
};

export type AccountType = "CHECKING" | "SAVINGS" | 
/**  Deferred debit card. */
"CREDIT_CARD" | 
/**  PEA, CTO, life insurance: only the total value is tracked in V1. */
"INVESTMENT" | 
/**  Real estate, vehicle… valued manually. */
"ASSET" | 
/**  Loan, tracked by its outstanding capital. */
"LIABILITY";

/**  Editable fields of an existing account. The type is fixed at creation. */
export type AccountUpdate = {
	name: string,
	institution: string | null,
	openingBalanceCents: number,
	openingDate: string,
};

export type AmbiguityReason = 
/**  The account has this exact operation, but fewer times than the file. */
"repeatedLine" | 
/**  An operation has the same date and amount, with another label. */
"sameDayOtherLabel" | 
/**  A manual entry has the same amount, a few days apart. */
"nearManualEntry";

/**  Where the amount of a line is read. Column indexes are zero-based. */
export type AmountColumns = 
/**  One signed amount column. */
{ kind: "signed"; amount: number } | 
/**  Separate debit and credit columns; their sign is ignored. */
{ kind: "debitCredit"; debit: number; credit: number };

/**
 *  Error returned by commands to the frontend: `{ kind, message, detail }`. `message` is the
 *  English description; `detail` is `null` for database, migration and I/O errors.
 */
export type AppError = {
	kind: ErrorKind,
	message: string,
	detail: ErrorDetail | null,
};

export type Attachment = {
	id: number,
	operationId: number,
	/**  Original file name. */
	fileName: string,
	sizeBytes: number,
	/**  `YYYY-MM-DDTHH:MM:SSZ`. */
	addedAt: string,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type AttachmentError = { code: "notFound"; params: number } | { code: "notAFile"; params: string } | { code: "tooLarge"; params: {
	maxBytes: number,
} } | { code: "fileMissing"; params: number };

export type BalanceCheck = {
	status: BalanceCheckStatus,
	/**  Sum of the statement lines. */
	linesTotalCents: number,
	/**  Start balance plus the lines; `None` without a start balance. */
	computedEndCents: number | null,
};

/**  Result of `start balance + Σ operations = end balance` on the statement. */
export type BalanceCheckStatus = "OK" | "MISMATCH" | 
/**  The statement gives no balances (CSV files). */
"NOT_AVAILABLE";

export type BalancePoint = {
	date: string,
	/**  Total balance of the accounts at the end of `date`. */
	balanceCents: number,
};

/**  Interval between two points of `balance_history`. */
export type BalanceStep = "day" | "week" | "month";

export type Category = {
	id: number,
	name: string,
	/**  `None` for a top-level category. Two levels at most. */
	parentId: number | null,
	color: CategoryColor,
	/**  System category excluded from income and expense statistics. */
	isInternalTransfer: boolean,
	isIncome: boolean,
	/**  Operations in this category (not counting its subcategories). */
	operationCount: number,
};

/**  Color family of a category, mapped to the `--cat-<color>` design tokens. */
export type CategoryColor = "housing" | "groceries" | "restaurants" | 
/**  Transport and income. */
"transport" | "leisure" | "subscriptions" | "health" | 
/**  Internal transfer and other. */
"neutral";

export type CategoryComparison = {
	/**  `None` for uncategorized expenses. */
	categoryId: number | null,
	/**  Net expenses of the period. */
	currentCents: number,
	/**  Net expenses of the compared period. */
	previousCents: number,
};

export type CategoryCount = {
	categoryId: number,
	count: number,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type CategoryError = { code: "notFound"; params: number } | { code: "emptyName" } | { code: "duplicateName"; params: string } | { code: "systemCategoryLocked" } | { code: "invalidParent" } | { code: "hasSubcategories" } | { code: "reassignToSelf" };

export type CategoryExpense = {
	/**  `None` for uncategorized expenses. */
	categoryId: number | null,
	/**  Net amount spent: positive, or negative when refunds exceed spending. */
	expenseCents: number,
};

/**  Category of the operations to keep. */
export type CategoryFilter = 
/**  Operations still to categorize. */
{ kind: "uncategorized" } | 
/**  Operations of the category, or of one of its subcategories. */
{ kind: "category"; id: number };

/**
 *  Fields of a category to create or update. For a subcategory, `color` and `is_income` are
 *  ignored: they come from the parent.
 */
export type CategoryInput = {
	name: string,
	parentId: number | null,
	color: CategoryColor,
	isIncome: boolean,
};

/**  How expenses are grouped by category. */
export type CategoryLevel = 
/**  Subcategories added to their top-level category. */
"topLevel" | 
/**  Each category as assigned. */
"detailed";

/**  Text encoding of a CSV file. */
export type CsvEncoding = "UTF-8" | "ISO-8859-1" | "WINDOWS-1252";

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type CsvError = { code: "invalidDelimiter"; params: string } | { code: "emptyDateFormat" } | { code: "invalidDateFormat"; params: string } | { code: "emptyStateValue" } | { code: "invalidEncoding"; params: string } | { code: "malformed"; params: {
	line: number,
	message: string,
} } | { code: "missingColumn"; params: {
	line: number,
	column: number,
} } | { code: "invalidDate"; params: {
	line: number,
	value: string,
} } | { code: "invalidAmount"; params: {
	line: number,
	value: string,
} } | { code: "wrongDecimalSeparator"; params: {
	line: number,
	value: string,
} } | { code: "missingAmount"; params: {
	line: number,
} } | { code: "bothDebitAndCredit"; params: {
	line: number,
} } | { code: "emptyLabel"; params: {
	line: number,
} };

/**  How to read the CSV export of a bank. Column indexes are zero-based. */
export type CsvMapping = {
	delimiter: string,
	encoding: CsvEncoding,
	/**  `chrono` format, e.g. `%d/%m/%Y`. */
	dateFormat: string,
	decimalSeparator: DecimalSeparator,
	columnDate: number,
	columnLabel: number,
	amountColumns: AmountColumns,
	/**  Lines ignored at the top of the file, column headers included. */
	skipLines: number,
	/**  Fees charged on top of the amount: the operation is the amount minus the fee. */
	columnFee: number | null,
	/**  Only the lines in this state are read (pending or reverted ones are skipped). */
	stateFilter: StateFilter | null,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type CsvMappingError = { code: "notFound"; params: number } | { code: "emptyName" } | { code: "duplicateName"; params: string } | { code: "corrupt"; params: number };

/**  Where the application keeps its data, for the Settings screen. */
export type DataLocation = {
	/**  The SQLite data file. */
	dataFile: string,
	/**  Directory of the automatic backups made before each import. */
	backupsDir: string,
	backupCount: number,
};

/**  First and last days of a period, both included. */
export type DateRange = {
	from: string,
	to: string,
};

/**  Decimal separator of the amounts. */
export type DecimalSeparator = "," | ".";

/**  Sign of the operations to keep. */
export type Direction = 
/**  Negative amounts. */
"debit" | 
/**  Positive amounts. */
"credit";

export type DuplicateStatus = { status: "new" } | { status: "duplicate"; operationId: number } | { status: "ambiguous"; reason: AmbiguityReason; 
/**  Existing operations the line may duplicate. */
candidateIds: number[] };

/**  Business error with its code and parameters, for a message in French on the frontend. */
export type ErrorDetail = { domain: "account"; error: AccountError } | { domain: "operation"; error: OperationError } | { domain: "category"; error: CategoryError } | { domain: "schedule"; error: ScheduleError } | { domain: "rule"; error: RuleError } | { domain: "payee"; error: PayeeError } | { domain: "tag"; error: TagError } | { domain: "attachment"; error: AttachmentError } | { domain: "transfer"; error: TransferError } | { domain: "stats"; error: StatsError } | { domain: "csv"; error: CsvError } | { domain: "csvMapping"; error: CsvMappingError } | { domain: "import"; error: ImportError } | { domain: "pdf"; error: PdfError };

/**  Stable identifier the frontend can match on. */
export type ErrorKind = "database" | "migration" | "io" | 
/**  The requested entity does not exist. */
"not_found" | 
/**  The input breaks a business rule; the message says which. */
"validation";

/**  An existing operation of the account, as needed for duplicate detection. */
export type ExistingOperation = {
	id: number,
	date: string,
	amountCents: number,
	rawLabel: string,
	isManual: boolean,
};

export type Frequency = "WEEKLY" | "MONTHLY" | "QUARTERLY" | "SEMIANNUAL" | "YEARLY";

/**  Length of the periods of `income_vs_expenses`. */
export type Granularity = "month" | "year";

export type ImportBatch = {
	id: number,
	accountId: number,
	sourceType: SourceType,
	sourceFileName: string,
	/**  SHA-256 of the file, in hexadecimal. */
	sourceFileHash: string,
	importedAt: string,
	statementStartBalanceCents: number | null,
	statementEndBalanceCents: number | null,
	balanceCheckStatus: BalanceCheckStatus,
	operationCount: number,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type ImportError = { code: "notFound"; params: number } | { code: "noLine" } | { code: "invalidLine" } | { code: "fileChanged" } | { code: "lineOutOfRange"; params: number } | { code: "duplicateLine"; params: number };

/**  How to read a statement file. */
export type ImportFormat = 
/**  CSV export read with a saved mapping. */
{ kind: "csv"; mappingId: number } | 
/**  PDF statement read by the parser of its bank, detected from its content. */
{ kind: "pdf" };

/**  Result of an import. */
export type ImportOutcome = {
	batch: ImportBatch,
	/**  Internal transfers linked automatically with operations of other accounts. */
	linkedTransfers: number,
	/**  Occurrences of scheduled operations realized automatically by the new operations. */
	matchedOccurrences: number,
};

export type ImportPreview = {
	fileName: string,
	/**  To check at import time that the file did not change. */
	fileHash: string,
	/**  Statement lines in file order; the import refers to them by index. */
	lines: PreviewLine[],
	/**  Existing operations that lines duplicate or may duplicate. */
	matchedOperations: ExistingOperation[],
	/**  Earlier imports of the same file, in any account. */
	previousImports: ImportBatch[],
	/**  Statement period, or else the dates of its first and last lines. */
	firstDate: string | null,
	lastDate: string | null,
	/**  Bank recognized from a PDF statement ("Format reconnu : …"). */
	bank: string | null,
	/**  Balances printed on the statement, when it gives them. */
	startBalanceCents: number | null,
	endBalanceCents: number | null,
	/**  `start balance + Σ lines = end balance`, over every line read. */
	balanceCheck: BalanceCheck,
};

/**  A preview line to import, with the category the user kept or chose. */
export type ImportSelection = {
	/**  Index of the line in the preview. */
	index: number,
	/**  `None`: to categorize. */
	categoryId: number | null,
};

export type LargestExpense = {
	operationId: number,
	date: string,
	normalizedLabel: string,
	payeeName: string,
	/**  Amount spent, positive. */
	expenseCents: number,
	categoryId: number | null,
};

/**  A saved mapping that reads a file without error. */
export type MappingSuggestion = {
	mapping: SavedCsvMapping,
	/**  Statement lines read from the file with this mapping. */
	lineCount: number,
};

/**  An operation matched, or to match, with an occurrence. */
export type MatchedOperation = {
	operationId: number,
	date: string,
	amountCents: number,
	/**  Payee name, or the normalized label when the operation has no payee. */
	payeeName: string,
};

export type NetWorth = {
	date: string,
	/**  Cash + investments + assets − liabilities. */
	netWorthCents: number,
	/**  Checking, savings and deferred debit card balances. */
	cashCents: number,
	investmentsCents: number,
	assetsCents: number,
	/**  Outstanding capital of the debts, as a positive amount. */
	liabilitiesCents: number,
};

/**  Fields chosen when creating an account. */
export type NewAccount = {
	name: string,
	type: AccountType,
	institution: string | null,
	openingBalanceCents: number,
	openingDate: string,
};

/**  A mapping to save, on creation or update. */
export type NewCsvMapping = {
	name: string,
	mapping: CsvMapping,
};

/**  A manual entry. */
export type NewOperation = {
	accountId: number,
	date: string,
	valueDate: string | null,
	amountCents: number,
	label: string,
	categoryId: number | null,
	note: string | null,
	/**  Tag names; unknown ones create a tag. */
	tags: string[],
};

/**  An operation with its category. V1 has exactly one split per operation. */
export type Operation = {
	id: number,
	accountId: number,
	date: string,
	valueDate: string | null,
	amountCents: number,
	/**  Original bank label, never modified. */
	rawLabel: string,
	/**  Cleaned label used for categorization and payees. */
	normalizedLabel: string,
	/**  Payee of the normalized label. */
	payeeId: number | null,
	/**  Name of the payee, or the normalized label when the operation has no payee yet. */
	payeeName: string,
	/**  `None` for manual entries. */
	importBatchId: number | null,
	/**  `None` while the operation is still to categorize. */
	categoryId: number | null,
	/**  Derived from the category; excluded from income and expense statistics. */
	isInternalTransfer: boolean,
	/**  The other side of the internal transfer, on another account, once linked. */
	transferPairId: number | null,
	note: string | null,
	/**  Tag names, by name. */
	tags: string[],
	attachmentCount: number,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type OperationError = { code: "notFound"; params: number } | { code: "categoryNotFound"; params: number } | { code: "emptyLabel" } | { code: "zeroAmount" } | { code: "accountWithoutOperations" } | { code: "dateBeforeOpening"; params: string } | { code: "importedFieldsLocked" } | { code: "importedOperationNotDeletable" };

/**  Filters combined with AND; a `None` filter keeps everything. Bounds are included. */
export type OperationFilter = {
	/**  `None` for every account. */
	accountId: number | null,
	/**  Whether archived accounts are searched when `account_id` is `None`. */
	includeArchived: boolean,
	from: string | null,
	to: string | null,
	direction: Direction | null,
	/**  Lowest amount, in absolute value. */
	minCents: number | null,
	/**  Highest amount, in absolute value. */
	maxCents: number | null,
	payeeId: number | null,
	category: CategoryFilter | null,
	tagId: number | null,
};

/**  An operation in a listing, with the balance of its account after it. */
export type OperationRow = {
	operation: Operation,
	balanceCents: number,
};

/**
 *  New values of an operation. For an imported operation, `date`, `amount_cents` and `label`
 *  must be left unchanged: only the value date, the category, the note and the tags can be
 *  edited.
 */
export type OperationUpdate = {
	date: string,
	valueDate: string | null,
	amountCents: number,
	label: string,
	categoryId: number | null,
	note: string | null,
	/**  Tag names; unknown ones create a tag. */
	tags: string[],
};

/**  A payee with its labels and the activity of its operations. */
export type Payee = {
	id: number,
	name: string,
	/**  Normalized labels merged into this payee, alphabetically. */
	labels: string[],
	operationCount: number,
	/**
	 *  Sum of the operation amounts, internal transfers excluded; `None` when all its
	 *  operations are internal transfers.
	 */
	totalCents: number | null,
	lastDate: string | null,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type PayeeError = { code: "notFound"; params: number } | { code: "labelNotFound"; params: string } | { code: "emptyName" } | { code: "nameTaken"; params: {
	name: string,
	payeeId: number,
} } | { code: "mergeIntoItself" } | { code: "lastLabel" };

export type PayeeExpense = {
	/**  `None` for operations without a payee yet, grouped by normalized label. */
	payeeId: number | null,
	payeeName: string,
	/**  Net amount spent with this payee, positive. */
	expenseCents: number,
	operationCount: number,
	/**  Category holding most of the amount; `None` when mostly uncategorized. */
	categoryId: number | null,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type PdfError = { code: "libraryUnavailable"; params: string } | { code: "invalidPdf"; params: string } | { code: "unknownFormat" } | { code: "layout"; params: string };

export type PeriodIncomeExpenses = {
	/**  First day of the month or year. */
	periodStart: string,
	incomeCents: number,
	/**  Positive amount spent, net of refunds. */
	expenseCents: number,
};

/**  A statement line in the import preview. */
export type PreviewLine = {
	line: RawLine,
	normalizedLabel: string,
	/**  Payee of the label, or the name its new payee will get. */
	payeeName: string,
	duplicate: DuplicateStatus,
	/**
	 *  Dated before the account opening: already counted in the opening balance, never
	 *  imported.
	 */
	beforeOpening: boolean,
	/**  Checked in the preview unless the user unchecks it: new lines only. */
	includedByDefault: boolean,
	/**
	 *  Category given at import: by the first matching rule, or else remembered for this
	 *  label; `None`: unknown label.
	 */
	categoryId: number | null,
	/**  Text of the rule that gave the category; `None` when remembered or unknown. */
	rulePattern: string | null,
};

/**
 *  A statement line as read from the bank file, before normalization and duplicate detection.
 *  Every parser (CSV mapping, bank-specific PDF parser) produces this structure.
 */
export type RawLine = {
	date: string,
	valueDate: string | null,
	/**  Label exactly as written by the bank, only trimmed. */
	label: string,
	/**  Negative for a debit, positive for a credit. */
	amountCents: number,
};

export type Rule = {
	id: number,
	/**  Text looked for in the normalized label, ignoring case and accents. */
	pattern: string,
	categoryId: number,
	/**  Operations still to categorize that the rule matches. */
	pendingCount: number,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type RuleError = { code: "notFound"; params: number } | { code: "emptyPattern" } | { code: "categoryNotFound"; params: number } | { code: "invalidOrder" };

/**  Fields of a rule to create or update. */
export type RuleInput = {
	pattern: string,
	categoryId: number,
};

/**  Other operations with the same normalized label as an operation, all accounts included. */
export type SameLabel = {
	normalizedLabel: string,
	/**  Others still to categorize. */
	uncategorized: number,
	/**  Others in another category than the operation, by category, the largest first. */
	otherCategories: CategoryCount[],
};

/**  A mapping saved under a name, e.g. "Banque X - export CSV". */
export type SavedCsvMapping = {
	id: number,
	name: string,
	mapping: CsvMapping,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type ScheduleError = { code: "notFound"; params: number } | { code: "emptyLabel" } | { code: "zeroAmount" } | { code: "invalidDay" } | { code: "endBeforeStart" } | { code: "accountWithoutOperations" } | { code: "categoryNotFound"; params: number } | { code: "notAnOccurrence"; params: string } | { code: "otherAccount" } | { code: "alreadyRealized" } | { code: "operationAlreadyMatched"; params: number };

/**  A detected match the user has to confirm. */
export type ScheduleMatchProposal = {
	occurrence: UpcomingOperation,
	operation: MatchedOperation,
};

export type ScheduledOperation = {
	id: number,
	accountId: number,
	label: string,
	/**  Negative for a debit, positive for a credit. */
	amountCents: number,
	categoryId: number | null,
	frequency: Frequency,
	dayOfPeriod: number,
	startDate: string,
	endDate: string | null,
};

/**  Fields of a scheduled operation to create or update. */
export type ScheduledOperationInput = {
	accountId: number,
	label: string,
	amountCents: number,
	categoryId: number | null,
	frequency: Frequency,
	dayOfPeriod: number,
	startDate: string,
	endDate: string | null,
};

export type SourceType = "CSV" | "PDF";

/**  Lines kept according to a state column, e.g. only `COMPLETED` operations. */
export type StateFilter = {
	column: number,
	/**  Value of the lines to read, compared without case; the other lines are skipped. */
	keep: string,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type StatsError = { code: "invalidPeriod"; params: {
	from: string,
	to: string,
} };

/**  A bank whose PDF statements can be imported. */
export type SupportedBank = {
	id: string,
	name: string,
};

/**  A tag with the count of its operations. */
export type Tag = {
	id: number,
	name: string,
	operationCount: number,
};

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type TagError = { code: "notFound"; params: number } | { code: "emptyName" } | { code: "nameTaken"; params: string };

/**  Serialized for the frontend as `{ code, params }`, to show a message in French. */
export type TransferError = { code: "sameAccount" } | { code: "amountsNotOpposite" } | { code: "alreadyLinked"; params: number };

/**  A detected transfer the user has to confirm. */
export type TransferProposal = {
	debit: TransferSide,
	credit: TransferSide,
};

/**  One side of a transfer, as shown to the user. */
export type TransferSide = {
	operationId: number,
	accountId: number,
	accountName: string,
	date: string,
	amountCents: number,
	/**  Payee name, or the normalized label when the operation has no payee. */
	payeeName: string,
};

/**  An occurrence of a scheduled operation. */
export type UpcomingOperation = {
	scheduledOperationId: number,
	date: string,
	accountId: number,
	label: string,
	amountCents: number,
	categoryId: number | null,
	/**  The operation that realized the occurrence, once matched. */
	realizedBy: MatchedOperation | null,
};

export type Valuation = {
	id: number,
	accountId: number,
	date: string,
	/**  Value, or outstanding capital for a debt: never negative. */
	valueCents: number,
};

/**  Date and value of a valuation to record or change. */
export type ValuationInput = {
	date: string,
	valueCents: number,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

